#[summary("과제 구현")]
mod tasks {
    spec fn same_len(old_v: &[u64], v: &[u64]) -> bool { v.len() == old_v.len() }

    #[effects(pure)]
    #[uses(same_len)]
    fn reverse(v: &mut [u64]) -> ()
        ensures same_len(old(v), v),
    {
        let len: usize = v.len();
        let mut n: usize = 0;
        while n < len / 2
            invariant len == v.len(), same_len(old(v), v),
            decreases len / 2 - n,
        {
            let x: u64 = v[n];
            let y: u64 = v[len - 1 - n];
            v[n] = y;
            v[len - 1 - n] = x;
            n = n + 1;
        }
    }
}
